function depthWeightedSum(nested: any[]): number {
  const walk = (list: any[], depth: number): number => {
    let total = 0;
    for (const x of list) total += Array.isArray(x) ? walk(x, depth + 1) : x * depth;
    return total;
  };
  return walk(nested, 1);
}

