function depthWeightedSum(nested: any[]): number {
  let level: any[] = nested, depth = 1, total = 0;
  while (level.length) {
    const next: any[] = [];
    for (const x of level) {
      if (Array.isArray(x)) for (const y of x) next.push(y);
      else total += x * depth;
    }
    level = next;
    depth++;
  }
  return total;
}

