class Solution:
    def depthWeightedSum(self, nested) -> int:
        level, depth, total = nested, 1, 0
        while level:
            nxt = []
            for x in level:
                if isinstance(x, list):
                    nxt.extend(x)
                else:
                    total += x * depth
            level = nxt
            depth += 1
        return total

